const $=s=>document.querySelector(s);let deck=[],page=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fit(){const w=$('#stage').clientWidth,h=$('#stage').clientHeight;$('#slide').style.transform=`scale(${Math.min(w/1920,h/1080)})`}
function show(n){page=(n+deck.length)%deck.length;const s=deck[page];$('#slide').innerHTML=s.elements.map(e=>{if(e.type==='text')return `<div class="slide-text" style="left:${e.x}px;top:${e.y}px;width:${e.w}px;font-size:${e.size}px;color:#${e.color};font-weight:${e.bold?700:400}">${e.url?`<a href="${esc(e.url)}" target="_blank">${esc(e.text)}</a>`:esc(e.text)}</div>`;if(e.type==='rect')return `<div style="position:absolute;left:${e.x}px;top:${e.y}px;width:${e.w}px;height:${e.h}px;background:#${e.color}"></div>`;if(e.type==='image')return `<img class="slide-img" src="${esc(e.path)}" alt="${esc(s.title)}" style="left:${e.x}px;top:${e.y}px;width:${e.w}px;height:${e.h}px;object-fit:${e.fit?'contain':'cover'}">`;return ''}).join('');$('#notes').textContent=s.notes;$('#jump').value=page;fit()}
fetch('deck.json').then(r=>r.json()).then(x=>{deck=x;$('#jump').innerHTML=x.map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${esc(s.title.replaceAll('\n',' '))}</option>`).join('');const picks=[3,5,7,12,14,16,18,19,24];$('#workgrid').innerHTML=picks.map(i=>{const s=x[i],im=s.elements.find(e=>e.type==='image');return `<a class="work" href="#talk" data-slide="${i}">${im?`<img loading="lazy" src="${im.path}" alt="${esc(s.title)}">`:''}<p>PROJECT / ${String(i+1).padStart(2,'0')}</p><h3>${esc(s.title.replaceAll('\n',' '))}</h3></a>`}).join('');document.querySelectorAll('[data-slide]').forEach(a=>a.onclick=()=>show(+a.dataset.slide));show(0)});
$('#prev').onclick=()=>show(page-1);$('#next').onclick=()=>show(page+1);$('#jump').onchange=e=>show(+e.target.value);$('#notesToggle').onclick=()=>$('#notes').hidden=!$('#notes').hidden;$('#full').onclick=()=>$('#stage').requestFullscreen();window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',fit);document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')show(page+1);if(e.key==='ArrowLeft')show(page-1);if(e.key.toLowerCase()==='f')$('#stage').requestFullscreen();if(e.key.toLowerCase()==='n')$('#notes').hidden=!$('#notes').hidden});
let memories=JSON.parse(localStorage.getItem('cai-memories')||'[]');function listMemories(items){$('#memoryOut').innerHTML=items.length?items.map(m=>`<div class="memoryitem"><b>${esc(m.name)}</b><small>${esc(m.time)}</small><p>${esc(m.text)}</p></div>`).join(''):'还没有匹配的记忆。'}
$('#remember').onclick=()=>{const text=$('#event').value.trim();if(!text)return;memories.unshift({name:$('#character').value||'未命名角色',text,time:new Date().toLocaleString()});localStorage.setItem('cai-memories',JSON.stringify(memories));$('#event').value='';listMemories(memories)};$('#recall').onclick=()=>listMemories(memories.filter(m=>m.text.includes($('#query').value.trim())));
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('#exportMemory').onclick=()=>download('角色记忆.json',JSON.stringify(memories,null,2),'application/json');
let cells=[];function city(){let seed=+$('#seed').value||1;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}cells=Array.from({length:192},(_,i)=>({x:i%16,y:Math.floor(i/16),on:rand()<+$('#density').value/100,h:rand()}));drawCity()}function drawCity(){const v=$('#cityView');v.innerHTML='<rect width="700" height="500" fill="#08090b"/>'+cells.map((c,i)=>`<rect data-cell="${i}" x="${30+c.x*40}" y="${20+c.y*38}" width="32" height="30" fill="${c.on?'#ff304a':'#242833'}" opacity="${c.on?.35+c.h*.65:1}"/>`).join('');v.querySelectorAll('[data-cell]').forEach(r=>r.onclick=()=>{cells[+r.dataset.cell].on=!cells[+r.dataset.cell].on;drawCity()})}$('#generate').onclick=city;$('#density').oninput=city;$('#exportCity').onclick=()=>download('蔡智鑫-空间实验.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 500">'+$('#cityView').innerHTML+'</svg>','image/svg+xml');city();
const canvas=$('#field'),ctx=canvas.getContext('2d');let pointer={x:-1000,y:-1000},particles=[];function reset(){particles=Array.from({length:650},()=>({x:Math.random()*900,y:Math.random()*550,vx:0,vy:0}))}reset();canvas.onpointermove=e=>{const b=canvas.getBoundingClientRect();pointer={x:(e.clientX-b.left)*900/b.width,y:(e.clientY-b.top)*550/b.height}};canvas.onpointerleave=()=>pointer={x:-1000,y:-1000};$('#resetParticles').onclick=reset;function animate(){if(!$('#body').hidden){ctx.fillStyle='rgba(8,9,11,.2)';ctx.fillRect(0,0,900,550);for(const p of particles){const dx=p.x-pointer.x,dy=p.y-pointer.y,l=Math.hypot(dx,dy),rad=+$('#radius').value;if(l<rad&&l>0){p.vx+=dx/l*.7;p.vy+=dy/l*.7}p.vx*=.97;p.vy*=.97;p.x=(p.x+p.vx+900)%900;p.y=(p.y+p.vy+550)%550;ctx.fillStyle=l<rad?'#ff304a':'#d4cbd4';ctx.fillRect(p.x,p.y,2,2)}}requestAnimationFrame(animate)}animate();document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.labpane').forEach(p=>p.hidden=p.id!==b.dataset.lab);document.querySelectorAll('[data-lab]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('[data-lab="memory"]').classList.add('active');
